const e = $input.first().json;
const hay = `${e.subject || ''} ${e.from || ''}`.toLowerCase();
const billing = /invoice|receipt|payment|billing|statement|order confirm/i.test(hay);
if (!billing) return [];
return [{ json: { subject: e.subject, from: e.from, date: e.date, text: (e.textPlain || e.textHtml || '').slice(0, 6000) } }];

