const raw = $input.first().json.message.content.trim();
if (raw === 'NOT_INVOICE') return [];
let data;
try { data = JSON.parse(raw.replace(/^```json?\s*|```$/g, '')); } catch { return []; }
const src = $('Billing Emails Only').first().json;
return [{ json: {
  Received: src.date || new Date().toISOString(),
  Vendor: data.vendor || '', Amount: data.amount || 0, Currency: data.currency || '',
  InvoiceNumber: data.invoice_number || '', InvoiceDate: data.invoice_date || '', DueDate: data.due_date || '',
  Subject: src.subject || ''
} }];
